    private void openWatch(double number,String playMode){if(anime.blocked)return;androidx.media3.exoplayer.offline.Download done=completed.get(DownloadHub.episodeKey(number));if(done!=null){Ui.openOffline(this,done.request.id,anime,number);return;}if(readyVoice(number)){Ui.openPlayer(this,anime,"yoru",number);return;}chooseWatchVoice(number,playMode);}
    private void chooseWatchVoice(double number,String playMode){java.util.concurrent.atomic.AtomicBoolean cancelled=new java.util.concurrent.atomic.AtomicBoolean(false);Ui.Progress wait=Ui.progress(this,"Загружаем озвучки серии "+Ui.number(number)+"…",true,()->cancelled.set(true));YoruApp.app().io.execute(()->{try{WatchPack pack=watchPack(number);YoruApp.app().main.post(()->{if(dead()||cancelled.get())return;wait.dismiss();showWatchDialog(pack,playMode);});}catch(Exception e){YoruApp.app().main.post(()->{if(dead()||cancelled.get())return;wait.dismiss();Ui.confirm(this,"Озвучки пока не загрузились","Можно открыть просмотр или попробовать ещё раз.","Открыть",()->Ui.openPlayer(this,anime,"yoru",number),"Отмена");});}});}
    private WatchPack watchPack(double number)throws Exception{Anime.Playback ready=YoruApp.app().api.playback(anime,"yoru");Anime.Episode ep=findEpisode(ready==null?null:ready.video,number);LinkedHashMap<String,String> voices=new LinkedHashMap<>();boolean unknown=false;if(ep!=null){String direct=ready!=null&&ready.video!=null?ApiRepository.sourceVoice(ready.video.source):"";if(!direct.isEmpty()&&!ep.streams.isEmpty())voices.put(ApiRepository.voiceKey(direct),direct);for(Anime.Variant v:SourceEngine.sortVariants(ep.variants)){String title=ApiRepository.voiceTitle(v.name.isEmpty()?v.label():v.name);String key=ApiRepository.voiceKey(title);if(!key.isEmpty()&&!voices.containsKey(key))voices.put(key,title);else if(key.isEmpty()&&!ApiRepository.embed(v.url).isEmpty())unknown=true;}}ArrayList<String> names=new ArrayList<>(),values=new ArrayList<>();names.add("Авто · лучшая доступная");values.add("");for(String title:voices.values()){names.add(title);values.add(title);}if(names.size()==1&&unknown)names.set(0,"Авто · дорожка без названия");SecureStore store=YoruApp.app().store;String pref=store.voicePreference();int selected=0;for(int i=1;i<values.size();i++){if(ApiRepository.voiceMatches(pref,values.get(i)))selected=i;else if(selected==0&&store.voicePriority(values.get(i))>=0)selected=i;}WatchPack pack=new WatchPack();pack.playback=ready;pack.episode=ep;pack.names=names.toArray(new String[0]);pack.values=values.toArray(new String[0]);pack.selected=selected;return pack;}
    private Anime.Episode findEpisode(Anime source,double number){if(source==null)return null;Anime.Episode fallback=null;double best=Double.MAX_VALUE;for(Anime.Episode ep:source.episodeList){if(ep==null)continue;if(Math.abs(ep.number-number)<0.001)return ep;double diff=Math.abs(ep.number-number);if(diff<best){best=diff;fallback=ep;}}return fallback;}
    private void showWatchDialog(WatchPack pack,String playMode){double number=pack.episode==null?progressCached.optDouble("episode",1):pack.episode.number;LinearLayout col=Ui.column(this);col.setPadding(Ui.dp(this,4),0,Ui.dp(this,4),0);TextView note=Ui.text(this,"Выберите озвучку и разрешение один раз. Следующие запуски этой серии откроются сразу.",12,Ui.MUTED,false);note.setLineSpacing(Ui.dp(this,4),1);col.addView(note);Ui.space(col,12);col.addView(Ui.text(this,"Озвучка",11,Ui.MUTED,false));Spinner voice=new Spinner(this);voice.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,pack.names));voice.setSelection(Math.max(0,Math.min(pack.selected,pack.names.length-1)));col.addView(voice,Ui.lp(this,-1,46));Ui.space(col,10);col.addView(Ui.text(this,"Разрешение",11,Ui.MUTED,false));Spinner quality=new Spinner(this);quality.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,QualityPlus.LABELS));quality.setSelection(qualityIndex(YoruApp.app().store.quality()));col.addView(quality,Ui.lp(this,-1,46));Ui.space(col,8);TextView current=Ui.text(this,"Сейчас: "+defaultVoiceName()+" · "+qualityName(YoruApp.app().store.quality()),10,Ui.PURPLE,false);col.addView(current);Ui.custom(this,"Серия "+Ui.number(number),col,"Смотреть",()->{String selected=pack.values[voice.getSelectedItemPosition()];int[] qualities=QualityPlus.values();YoruApp.app().store.settings(qualities[quality.getSelectedItemPosition()],YoruApp.app().store.autoNext());applyVoice(selected);Ui.openPlayer(this,anime,"yoru",number);},"Скачать",()->{String selected=pack.values[voice.getSelectedItemPosition()];int[] qualities=QualityPlus.values();YoruApp.app().store.settings(qualities[quality.getSelectedItemPosition()],YoruApp.app().store.autoNext());applyVoice(selected);DownloadActions.prepare(this,anime,pack.playback,number);render();},"Отмена");}
    private void applyVoice(String selected){String voice=selected==null?"":selected;YoruApp.app().store.voicePreference(voice);if(!voice.isEmpty()){YoruApp.app().store.rememberVoice(voice);Ui.toast(this,"Озвучка добавлена в любимые: "+ApiRepository.voiceTitle(voice));}}
